const baseConfig: any = {
    mode: 'upsell-modal',
    planIDs: { [PLANS.MAIL]: 1, [ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS]: 1 },
    step: SUBSCRIPTION_STEPS.CHECKOUT,
    disablePlanSelection: true,
    upsellRef: 'upsellRef',
